* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #142b2b;
  color: #f4f0dc;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: #142b2b;
  background-image: linear-gradient(#244040 1px, transparent 1px), linear-gradient(90deg, #244040 1px, transparent 1px);
  background-size: 24px 24px;
}

.thermostat {
  width: min(100%, 440px);
  padding: 32px;
  background: #203a39;
  border: 4px solid #91b49a;
  box-shadow: 8px 8px 0 #0b1d1d;
}

.eyebrow, .display-label, .mode-label, .step, .range {
  font-size: .875rem;
  font-weight: 750;
  letter-spacing: .12em;
}

.eyebrow { margin: 0 0 8px; color: #a8cbb0; }
h1 { margin: 0; font-size: clamp(1.65rem, 7vw, 2rem); line-height: 1.2; }
.room { display: flex; justify-content: space-between; align-items: center; margin: 24px 0 12px; color: #bed0bc; font-size: .9rem; letter-spacing: .06em; }
.room strong { color: #f4f0dc; font-size: 1.1rem; }

.display {
  position: relative;
  min-height: 150px;
  padding: 18px 20px;
  display: flex;
  align-items: baseline;
  justify-content: center;
  background: #142b2b;
  border: 3px solid #52776b;
}
.display-label { position: absolute; top: 12px; left: 14px; color: #91b49a; }
.temperature { align-self: center; margin-top: 18px; font-size: clamp(3.5rem, 16vw, 5rem); font-variant-numeric: tabular-nums; font-weight: 750; line-height: 1; color: #d6e9ae; }
.unit { align-self: center; margin: 20px 0 0 8px; color: #d6e9ae; font-size: 1.5rem; }

.adjustments { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 16px; margin: 18px 0 24px; }
.adjust {
  min-height: 54px;
  border: 3px solid #91b49a;
  background: #31524c;
  color: #f4f0dc;
  font: inherit;
  font-size: 1.8rem;
  font-weight: 750;
  cursor: pointer;
  box-shadow: 3px 3px 0 #0b1d1d;
}
.adjust:hover { background: #42665c; }
.adjust:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #0b1d1d; }
.adjust:focus-visible, select:focus-visible { outline: 3px solid #e4d276; outline-offset: 3px; }
.step { color: #bed0bc; text-align: center; white-space: nowrap; }

.mode-label { display: block; margin-bottom: 8px; color: #a8cbb0; }
select {
  width: 100%;
  min-height: 52px;
  padding: 0 14px;
  border: 3px solid #91b49a;
  border-radius: 0;
  background: #142b2b;
  color: #f4f0dc;
  font: inherit;
  font-size: 1rem;
  cursor: pointer;
}
.status { display: flex; align-items: center; gap: 10px; min-height: 56px; margin: 20px 0 0; padding: 12px 14px; border: 2px solid #52776b; font-size: 1.05rem; font-weight: 700; }
.status-dot { width: 12px; height: 12px; flex: 0 0 12px; background: #d6e9ae; box-shadow: 0 0 0 3px #31524c; }
.status[data-state="heating"] .status-dot { background: #e4a66d; }
.status[data-state="cooling"] .status-dot { background: #83c6d0; }
.status[data-state="idle"] .status-dot { background: #d6e9ae; }
.range { display: flex; justify-content: space-between; gap: 12px; margin: 18px 0 0; color: #91b49a; font-size: .75rem; }
.range span { color: #bed0bc; letter-spacing: .04em; }

@media (max-width: 420px) {
  body { padding: 16px; }
  .thermostat { padding: 24px 20px; }
  .adjustments { gap: 10px; }
  .step { font-size: .75rem; }
}

const roomTemperature = 21;
const minTemperature = 10;
const maxTemperature = 30;
const step = 0.5;

const temperatureOutput = document.getElementById('temperature');
const modeSelect = document.getElementById('mode');
const status = document.getElementById('status');
const statusText = document.getElementById('statusText');
let targetTemperature = roomTemperature;

function updateStatus() {
  const mode = modeSelect.value;
  let message = 'Idle';
  let state = 'idle';

  if (mode === 'Heat' && targetTemperature > roomTemperature) {
    message = 'Heating';
    state = 'heating';
  } else if (mode === 'Cool' && targetTemperature < roomTemperature) {
    message = 'Cooling';
    state = 'cooling';
  }

  statusText.textContent = message;
  status.dataset.state = state;
}

function adjustTemperature(amount) {
  targetTemperature = Math.min(maxTemperature, Math.max(minTemperature, targetTemperature + amount));
  temperatureOutput.value = targetTemperature.toFixed(1);
  temperatureOutput.textContent = targetTemperature.toFixed(1);
  updateStatus();
}

document.getElementById('minus').addEventListener('click', () => adjustTemperature(-step));
document.getElementById('plus').addEventListener('click', () => adjustTemperature(step));
modeSelect.addEventListener('change', updateStatus);
updateStatus();
